{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A practical, humane approach to building habits, sustainable rhythms, and clearer days. Outcomes, habits, frameworks.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-zen">
  <header class="site-header">
    <div class="container">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="/about.html">Who I Am</a>
        <a href="/services.html">Offerings</a>
        <a href="/programs.html">Journeys</a>
        <a href="/pricing.html">Rates</a>
        <a href="/testimonials.html">Voices</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="/contact.html" class="muted">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="home">
      <svg class="pattern-bg" aria-hidden="true"><use href="assets/img/pattern.svg#p"></use></svg>
      <div class="container hero-inner">
        <div class="intro">
          <h1 class="title">Small frames. Lasting clarity.</h1>
          <p class="lede">I help you translate intention into repeatable, trackable habits—without moralizing or dieting your life. Outcomes, habits, and a forward-facing framework.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button class="btn ghost" id="try-breathe">Try a breath now</button>
            <button class="btn ghost" id="try-journal">Try a prompt</button>
          </div>
        </div>
        <aside class="hero-tools">
          <div class="card">
            <h4>7-day practice builder</h4>
            <p>Create a short, printable checklist to start a habit that fits your week.</p>
            <div class="tool">
              <label for="habit-type">Focus</label>
              <select id="habit-type">
                <option value="hydration">Hydration</option>
                <option value="movement">Morning Movement</option>
                <option value="sleep">Wind-down</option>
                <option value="journaling">Micro-journaling</option>
                <option value="breath">Breathing pause</option>
              </select>
              <label for="habit-goal">Daily commitment</label>
              <input id="habit-goal" placeholder="e.g., 5 min, 20 oz, 10 squats">
              <button id="generate-challenge" class="btn">Make my 7-day checklist</button>
            </div>
          </div>
        </aside>
      </div>
    </section>

    <!-- PILLARS: Core practices -->
    <section class="pillars container" id="pillars">
      <h2>Three guiding moves</h2>
      <p class="sub">Each pillar is a simple lever you can use today.</p>
      <div class="grid">
        <div class="pill">
          <h3>Micro-habits</h3>
          <p>Short, repeatable actions designed to stack into days. Measured in minutes or reps, not obligation.</p>
        </div>
        <div class="pill">
          <h3>Signals & anchors</h3>
          <p>Contextual cues that make actions automatic—place, routine, or a gentle ritual to cue the habit.</p>
        </div>
        <div class="pill">
          <h3>Outcomes-first planning</h3>
          <p>Define the outcome you care about, then build the smallest actions that reliably point there.</p>
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section class="myths container" id="myths">
      <h2>Myth vs. a kinder truth</h2>
      <dl>
        <div>
          <dt>Myth: Willpower is all you need.</dt>
          <dd>Truth: Design and tiny, repeatable cues matter more than big motivational bursts.</dd>
        </div>
        <div>
          <dt>Myth: Faster means better.</dt>
          <dd>Truth: A paced approach that fits your life lasts longer than a sprint.</dd>
        </div>
        <div>
          <dt>Myth: Change must be dramatic.</dt>
          <dd>Truth: Gentle, measurable shifts accumulate into dependable days.</dd>
        </div>
      </dl>
    </section>

    <!-- CASE NOTES -->
    <section class="case-notes container" id="case-notes">
      <h2>Short case notes</h2>
      <p class="sub">Real examples of subtle changes that moved the needle.</p>
      <ul class="notes">
        <li>
          <strong>Outcome:</strong> More consistent mornings. <em>Habit:</em> 3-minute movement after putting coffee on. <span class="muted">— 8 weeks</span>
        </li>
        <li>
          <strong>Outcome:</strong> Better evening rest. <em>Habit:</em> 10-minute wind-down journaling, no screens. <span class="muted">— 6 weeks</span>
        </li>
        <li>
          <strong>Outcome:</strong> Less afternoon crash. <em>Habit:</em> 12 oz hydration at 2pm. <span class="muted">— 3 weeks</span>
        </li>
      </ul>
    </section>

    <!-- FAQ -->
    <section class="faq container" id="faq">
      <h2>Questions people ask</h2>
      <details>
        <summary>Is this therapy or medical care?</summary>
        <p>No. This work focuses on habits, frameworks, and practical support for day-to-day wellbeing. It does not provide medical diagnosis or treatment.</p>
      </details>
      <details>
        <summary>How long before I notice a difference?</summary>
        <p>Small shifts can feel notable in as little as two weeks, but the aim is reliable routines you can sustain over months.</p>
      </details>
      <details>
        <summary>Do you offer planning for groups?</summary>
        <p>Yes—programs and coaching can be scaled for small teams or circles. Reach out to discuss structure and pricing.</p>
      </details>
    </section>

    <!-- CALL TO ACTION -->
    <section class="cta container" id="cta">
      <div class="card">
        <h3>Ready to form a habit that fits your life?</h3>
        <p>Book a short discovery session and we’ll map one clear, trackable practice for your week.</p>
        <div class="actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/contact.html">Ask a quick question</a>
        </div>
        <p class="contact small">Prefer to call? <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container">
      <p class="muted">Serving clients in {{CITY}}, {{STATE}} and remote. Outcomes, habits, frameworks — no medical claims.</p>
      <p class="muted">© <span id="year"></span> {{BUSINESS_NAME}} • <a href="/privacy.html">Privacy</a> • <a href="/terms.html">Terms</a></p>
    </div>
  </footer>

  <!-- MODALS -->
  <div id="modal" class="modal" aria-hidden="true">
    <div class="modal-panel" role="dialog" aria-modal="true">
      <button class="modal-close" id="modal-close">Close</button>
      <div id="modal-content"></div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
  <script>document.getElementById('year').textContent = new Date().getFullYear();</script>
</body>
</html>"} 
